#include <stdio.h>

int tests_pass = 0, tests_fail = 0;

#define ASSERT_EQ(a, b) do { \
    if ((a) != (b)) { printf("FAIL (line %d)\n", __LINE__); tests_fail++; } \
    else { printf("PASS\n"); tests_pass++; } \
} while(0)

#define ASSERT_TRUE(c) do { \
    if (!(c)) { printf("FAIL (line %d)\n", __LINE__); tests_fail++; } \
    else { printf("PASS\n"); tests_pass++; } \
} while(0)

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }

int main() {
    printf("Test add: "); ASSERT_EQ(add(2, 3), 5);
    printf("Test sub: "); ASSERT_EQ(sub(5, 3), 2);
    printf("Test true: "); ASSERT_TRUE(1);
    printf("\nPassed: %d, Failed: %d\n", tests_pass, tests_fail);
    return 0;
}
